INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (109, 105, 'Chính Sách & Điều Kiện Sử Dụng: Đệ Nhất - Buffet Thứ 7 Cuối Tuần Sang Xịn Bên Hồ Bơi', $BODY$Điều kiện sử dụng

