INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (113, 107, 'Chính Sách & Điều Kiện Sử Dụng: Towa Japanese Cuisine Tầng 28 Sedona Suites - Omakase Cao Cấp Cho 1 Người', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: từ 31/07/2026 đến 31/07/2027.

- Địa điểm sử dụng voucher: Towa Japanese Cuisine & Louge - Tầng 28 Sedona Suites (Bên cạnh Sài Gòn Center) 92-94 Nam Kỳ Khởi Nghĩa, Phường Sài Gòn, TP. Hồ Chí Minh.

