INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (115, 108, 'Chính Sách & Điều Kiện Sử Dụng: Towa Japanese Cuisine Tầng 28 Sedona Suites - Cua Lông Kegani Cho 2 Người', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: từ 31/07/2026 đến 31/07/2027.

- Địa điểm sử dụng voucher: Towa Japanese Cuisine & Louge - Tầng 28 Sedona Suites (Bên cạnh Sài Gòn Center) 92-94 Nam Kỳ Khởi Nghĩa, Phường Sài Gòn, TP. Hồ Chí Minh.

- Khách hàng mua voucher Hotdeal, vui lòng liên hệ  đặt chỗ trước 24 giờ khi đến theo số hotline: 0903 116 038.

- Việc đặt bàn phụ thuộc vào tình trạng chỗ trống và khả năng phục vụ của nhà hàng.

- Voucher áp dụng cho 1 Con Cua Lông Cao Cấp Nhật Bản Kegani 600gr (2 món cho 2 người) - Ngắm trọn view Sài Gòn về đêm từ tầng 28.

- Lựa chọn các cách chế biến:

1/ Trứng hấp

2/ Cơm trứng

3/ Cua đút lò phô mai

- Thời gian phục vụ: Mỗi ngày 11h30-22h00 l Last order 21h45

- Sử dụng 01 voucher/ 2 người. Giá đã bao gồm VAT và phí phục vụ.

- Khách hàng phải xuất trình mã voucher hợp lệ trước khi sử dụng dịch vụ.

- Mỗi voucher chỉ được sử dụng một lần, cho một bàn và một hóa đơn.

- Voucher không được quy đổi thành tiền mặt, không hoàn lại tiền thừa và không dùng để mua voucher hoặc thẻ

- Không áp dụng đồng thời với MBS Card, ưu đãi thành viên, chiết khấu 15%, voucher tiền mặt hoặc chương trình khuyến mãi khác.

- Không tách bàn, gộp bàn hoặc tách hóa đơn nhằm sử dụng nhiều ưu đãi cho cùng một nhóm khách.

- Phần phát sinh ngoài nội dung voucher được thanh toán theo giá niêm yết hiện hành của nhà hàng.

- Voucher không áp dụng vào ngày lễ, Tết và các dịp đặc biệt theo thông báo của nhà hàng (1/1, 14/2, 8/3, 30/4, 1/5, 1/6, 2/9, 24/12, 31/12).

- Hình ảnh món ăn chỉ mang tính chất minh họa. Một số nguyên liệu có thể được thay thế bằng sản phẩm có giá trị tương đương khi cần thiết.

- Khách hàng vui lòng thông báo trước về dị ứng thực phẩm hoặc yêu cầu ăn uống đặc biệt. Nhà hàng sẽ hỗ trợ trong phạm vi có thể.

- Thanh toán online nhận ngay voucher điện tử.$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (116, 108, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Towa Japanese Cuisine Tầng 28 Sedona Suites - Cua Lông Kegani Cho 2 Người', $BODY$Thông tin chi tiết

Nằm trên tầng 28 Sedona Suites, ngay cạnh Saigon Centre, Towa Japanese Cuisine & Lounge là điểm đến dành cho những thực khách yêu thích ẩm thực Nhật Bản cao cấp. Sở hữu không gian sang trọng, thiết kế tinh tế cùng tầm nhìn bao quát thành phố, nhà hàng mang đến trải nghiệm vừa thưởng thức những món ăn thượng hạng, vừa chiêm ngưỡng khung cảnh Sài Gòn rực rỡ khi màn đêm buông xuống.

Lấy cảm hứng từ nghệ thuật ẩm thực Nhật Bản, Towa Japanese Cuisine & Lounge chú trọng lựa chọn những nguyên liệu tươi ngon được nhập khẩu và chế biến theo phong cách tinh tế nhằm giữ trọn hương vị nguyên bản. Mỗi món ăn đều được chăm chút từ hương vị đến cách trình bày, mang đến hành trình ẩm thực trọn vẹn cho cả vị giác lẫn thị giác. Không gian thanh lịch cùng phong cách phục vụ chuyên nghiệp khiến Towa trở thành lựa chọn lý tưởng cho những buổi hẹn hò, kỷ niệm hay những dịp đặc biệt bên người thân.

Voucher Hotdeal áp dụng cho 01 con Cua Lông Cao Cấp Nhật Bản Kegani 600g, được chế biến thành 02 món đặc sắc dành cho 02 người. Kegani là một trong những loại cua nổi tiếng của Nhật Bản, được yêu thích bởi phần thịt ngọt chắc, gạch cua béo ngậy và hương vị đậm đà đặc trưng, được xem là một trong những nguyên liệu cao cấp trong ẩm thực xứ sở hoa anh đào.

Thực khách sẽ được thưởng thức Trứng hấp mềm mịn, thơm béo, hòa quyện cùng vị ngọt tự nhiên của cua lông. Hoặc Cơm trứng, món ăn hấp dẫn với phần gạch cua béo ngậy kết hợp cùng cơm nóng, mang đến hương vị đậm đà khó quên. Cua lông đút lò phô mai, sự kết hợp độc đáo giữa thịt cua ngọt thanh và lớp phô mai béo thơm, tạo nên món ăn vừa hấp dẫn vừa tinh tế là mòn ăn mà thực khách không thể bỏ qua.

Không chỉ là cơ hội thưởng thức một trong những đặc sản nổi tiếng của Nhật Bản, đây còn là dịp để tận hưởng không gian đẳng cấp cùng khung cảnh Sài Gòn về đêm từ tầng 28, mang đến một buổi tối lãng mạn và đáng nhớ dành cho hai người.

Click MUA và trải nghiệm ngay nào!$BODY$, 'ARTICLE', 'ACTIVE');


