INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (117, 109, 'Chính Sách & Điều Kiện Sử Dụng: VTM Úc Châu - Massage Body + Ấn Huyệt + Foot + Đầu, Cổ, Vai, Gáy', $BODY$Điều kiện sử dụng

