INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (133, 117, 'Chính Sách & Điều Kiện Sử Dụng: Suối Tiên - Combo Vé Cổng + Trò Chơi Biển Tiên Đồng - Ngọc Nữ', $BODY$Điều kiện sử dụng

