INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (139, 120, 'Chính Sách & Điều Kiện Sử Dụng: Đầm Sen - Vé Trọn Gói Vào Cổng + 35 Trò Chơi Hấp Dẫn', $BODY$Điều kiện sử dụng

- Deal chỉ áp dụng E-voucher. Sau khi thanh toán đơn hàng thành công thì EVC sẽ được gửi vào tin nhắn qua số điện thoại của quý khách.

- Xuất trình và quét EVC Hotdeal tại cổng - vào ngay, không cần mua vé tại quầy.

- Thời hạn sử dụng voucher: từ 28/04/2026 đến 28/11/2026.

- Địa điểm sử dụng voucher: Công viên Văn hóa Đầm Sen - Số 03 Hòa Bình, Phường 3, Quận 11, Tp.HCM. ĐT: (028) 3963 4963.

- Website: http://damsenpark.com.vn/

- Facebook: https://www.facebook.com/damsenpark.vn/

- Áp dụng: Vé trọn gói có giá trị vào cổng + xem biểu diễn Lakeshow nhạc nước hoành tráng + tham gia 35 trò chơi kể cả các trò chơi mới như: Power Surge, Lâu đài kỳ thú, Nhà hơi thể thao liên hoàn, 3 trò chơi Khu 9D tương tác ảo (9D Virtual Reality, Rune Raider, Turbo Racing) tại Công viên Văn hóa Đầm Sen. Không áp dụng cho các trò chơi ngoài danh mục vé trọn gói thông thường bao gồm: Xe điện, Thủy cung, Massage cá, Trò chơi dân gian, bắn súng sơn, đi luồng ưu tiên...

- Đầm Sen với rất nhiều cảnh check - in &ldquo;đẹp mê mẩn&rdquo;: Cầu vồng chân mây, Vườn Nhật Bản, Vườn Xương Rồng, Vườn Nam Tú Thượng Uyển,...

- Vô số trò chơi nhìn thôi đã muốn chinh phục: Tàu lượn siêu tốc, Thảm bay, Phượng hoàng bay, Cá chép nhào lộn, Vượt thác, Xe điện đụng đại dương,...

- Tuổi thơ ùa về với những trò chơi thần tiên dành cho các bé: Ếch nhảy, Điệu nhảy thiên thần, Vòng lượn tuổi thơ, Câu cá,...

- Livestream cực nét và sống ảo trong thế giới tuyệt vời với wifi free cực mạnh phủ sóng khắp công viên.

- Tham khảo danh sách trò chơi tại đây.

- Bảng giá tham khảo tại đây.

- Thời gian hoạt động: 8h - 18h từ thứ 2 đến thứ 6 & 8h - 19h thứ 7, chủ nhật hàng tuần (trừ thứ 3 hàng tuần). Riêng lễ, tết, sự kiện theo lịch hoạt động của công viên.

- Công viên không hoạt động thứ 3 hàng tuần. Riêng các sự kiện, các đợt lễ trong giai đoạn này nếu rơi vào thứ 3, công viên vẫn tổ chức hoạt động kinh doanh.

- Khách hàng đi vào các ngày lễ, tết vui lòng thanh toán thêm phụ thu bằng chênh lệch giá vé thực tế Đầm Sen tại thời điểm đó trừ đi: 300.000 đồng/ 01 vé trọn gói (thu tiền trực tiếp tại công viên).

- Sử dụng 01 voucher/ 01 người/ 01 lần (không phân biệt độ tuổi, không bù thêm tiền trừ ngày lễ, tết).

- Không hỗ trợ đổi trả trong bất cứ mọi trường hợp.

- Một khách hàng được mua nhiều phiếu.

- Không áp dụng đồng thời với các chương trình khuyến mãi khác.

- Phiếu không có giá trị quy đổi thành tiền mặt, không trả lại tiền thừa.

- Thanh toán online nhận ngay voucher điện tử.$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (140, 120, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Đầm Sen - Vé Trọn Gói Vào Cổng + 35 Trò Chơi Hấp Dẫn', $BODY$Thông tin chi tiết

CVVH ĐẦM SEN THI&Ecirc;N ĐƯỜNG VUI CHƠI CỰC Đ&Atilde; - ĐẾN CHƠI CHẲNG MUỐN VỀ

KHÁM PHÁ THẾ GIỚI CỦA NHỮNG TRÒ CHƠI HẤP DẪN TẠI ĐẦM SEN

TR&Igrave;NH DIỄN NHẠC NƯỚC + LASER - SHOW DIỄN CỰC ĐỈNH KH&Ocirc;NG THỂ BỎ QUA

Công viên Văn hóa Đầm Sen là một trong những khu vui chơi, giải trí được đông đảo đối tượng yêu thích với những trò chơi đầy vui nhộn, sự lựa chọn lý tưởng cho cả người lớn và trẻ em khi muốn giải trí, xua tan căng thẳng sau những giờ học tập và làm việc mệt mỏi. Đặc biệt, sử dụng vé trọn gói do Hotdeal mang đến lần này, quý khách sẽ được miễn vé cổng, xem biểu diễn Lakeshow nhạc nước hoành tráng và tham gia 35 trò chơi kể cả các trò chơi mới như: Power Surge, Lâu đài kỳ thú, Nhà hơi thể thao liên hoàn, 3 trò chơi Khu 9D tương tác ảo (9D Virtual Reality, Rune Raider, Turbo Racing) với giá chỉ 209.000 đồng.

CVVH Đầm Sen, tọa lạc tại Số 3 đường Hòa Bình, Quận 11, Tp.HCM

Cảnh đẹp làm say lòng người ở các địa điểm du lịch nổi tiếng Việt Nam hội tụ tại Đầm Sen (khung cảnh trang trí thay đổi phù theo các mùa trong năm).

​

Quảng trường chim bồ câu

Thành phố ngàn hoa

Nông trại cún sống ảo siêu dễ thương

Làng hương xứ Huế

Trang trí mùa lễ hội

Nam Tú Thượng Uyển

Rực rỡ Phố &Ocirc; Mưa tại Đầm Sen

Nhạc nước Đầm Sen Lake Show

Nhạc nước Lake Show đã ra mắt và được du khách đón nhận với sự thích thú và hào hứng. Công nghệ tân tiến nhất về âm thanh và ánh sáng đã được ứng dụng trong màn trình diễn nhạc nước. Công trình được đầu tư với một màn hình khổng lồ, được tạo bằng hệ thống phun nước. Kích thước màn hình có chiều ngang 40 mét và chiều cao 30 mét hình rẽ quạt. Màn hình này sẽ dùng để chiếu hình ảnh 3D về những cảnh đẹp ngoạn mục của Việt Nam và tái hiện trận chiến Bạch Đằng Giang oai hùng của Ngô Quyền.

Đầm Sen Lake Show còn có một hệ thống nhạc nước rộng dài suốt trên mặt hồ Đầm Sen. Hệ thống này được các chuyên gia lập trình biểu diễn theo từng phách nhạc, và cảm xúc của từng âm giai. Bên cạnh đó, để phụ họa cho những màn biểu diễn nước vào buổi tối còn có thêm phần khói lửa ngay trên mặt hồ. Hệ thống này được thiết kế tỉ mỉ đến từng chi tiết khi đi ngầm dưới lòng hồ. Chưa hết, hệ thống đèn laser kết hợp cùng chơi theo nhạc sẽ chiếu trên không gian của hồ tạo nên sự ảo diệu của những đêm biểu diễn.

Gợi ý xem Lake Show vào buổi tối là đẹp nhất. Không khí trong lành mát mẻ, ẩm thực đường phố hấp dẫn.

Cầu tàng hình: địa điểm sống ảo Hot nhất tại Đầm Sen

Cầu đúng nghĩa là &ldquo;tàng hình&rdquo;, bởi khi đứng trên bờ, người xem không thấy cây cầu mà chỉ thấy người đi trên mặt nước. Cầu đặt ở khu bờ Đông của hồ Đầm Sen (khu vực ẩm thực). Hậu cảnh của &ldquo;Địa điểm sống ảo&rdquo; này là nét duyên dáng của cầu Cửu Khúc. Đồng thời điểm tô bằng chiếc đu quay đứng khổng lồ của Đầm Sen. Đây là vị trí đẹp nhất để tạo ra những bức ảnh &ldquo;sống ảo&rdquo; tuyệt diệu.

Cầu tàng hình

Cầu vồng chân mây

&ldquo;Cầu vồng chân mây&rdquo; được các kỹ sư và chuyên gia nghiên cứu thiết kế thi công trong 1 tháng. &ldquo;Địa điểm sống ảo&rdquo; này đặt ở bờ Đông hồ Đầm Sen. Cầu có chiều dài 10 mét, nghiêng 45 độ, hướng ra hồ. Khung đế cầu được làm chắc chắn bằng khung sắt chịu lực. Khác với những chiếc cầu thiên đường như ở Đà Lạt, hay Tây Nguyên, chiếc cầu &ldquo;lên trời&rdquo; của Đầm Sen lại mô tả &ldquo;cầu vồng 7 sắc&rdquo;. Chính vì thế người ta gọi đây là &ldquo;Cầu vồng chân mây&rdquo;.

Cầu vồng chân mây

Quảng trường Kỳ quan thế giới

&ldquo;Địa điểm sống ảo&rdquo; với những kỳ quan thế giới tại Đầm Sen gồm: Quảng trường Đỏ (Nga); biểu tượng văn hóa Charminar (Ấn Độ); đấu trường La Mã Colosseum (Italy); Ngọn hải đăng Alexandria (Ai Cập); Tượng thần Mặt Trời khổng lồ ở Rhodes (Hy Lạp); Tháp nghiêng Pisa (Italy); Thần Vệ Nữ (Anh)... Buổi tối, các tác phẩm kỳ quan thu nhỏ này được chiếu sáng bằng công nghệ đèn LED và Laser khiến các tác phẩm thêm lung linh, huyền ảo.

Quảng trường Kỳ quan thế giới

Chìm đắm trong cái lạnh âm 15 độ C của Băng Đăng Đầm Sen

Tàu lượn siêu tốc

Power Surge

Trò chơi mới với công nghệ châu &Acirc;u, trải nghiệm cảm giác xoay 360 độ cực mạnh ở độ cao 20m.

Diễn viên - MC Đình Toàn chinh phục Power Surge

Vui cùng thảm bay

Lâu Đài Kỳ Thú

Bao gồm 2 khu riêng biệt cho người lớn và trẻ em, với hàng chục trò chơi công nghệ tương tác ảo cực kỳ hiện đại

lần đầu tiên có mặt tại Việt Nam

9D Virtual Reality, với chiếc kính thực tế ảo, hình ảnh xuất hiện phụ thuộc vào hướng quay đầu của người xem, cùng với âm thanh sống động và các hiệu ứng như mưa, gió, rắn bò chân, rung lắc...

Với Rune Raider, bạn sẽ được nhập vai để trở thành những tay bắn súng thiện xạ bách phát bách trúng và chiến thắng trong các cuộc đấu súng.

Turbo Racing - dành cho những ai có sở thích ưa mạo hiểm, ưa tốc độ cao thì trổ tài điều khiển siêu xe để trở thành tay đua kiệt xuất.

Lâu đài Kỳ Thú - nhiều trò chơi dành cho thiếu nhi

Nhà hơi thể thao liên hoàn 7 cấp độ cho bạn tha hồ trải nghiệm hoạt động ngoài trời với những chướng ngại vật vượt khó đầy sáng tạo,

có thể nhún nhảy, đùa nghịch và chinh phục thử thách.

